public:
    int numberOfWays(string s, string t, long long k) {
        long long mod = 1e9 + 7;
        int n = s.size();
        string ss = s + s;
        ss.pop_back();
        vector<int> pi(n, 0);
        int j = 0;
        for (int i = 1; i < n; i++) {
            while (j > 0 && t[i] != t[j]) j = pi[j - 1];
            if (t[i] == t[j]) j++;
            pi[i] = j;
        }
        int c = 0;
        j = 0;
        for (int i = 0; i < ss.size(); i++) {
            while (j > 0 && ss[i] != t[j]) j = pi[j - 1];
            if (ss[i] == t[j]) j++;
            if (j == n) {
                c++;
                j = pi[j - 1];
            }
        }
        auto power = [&](long long base, long long exp) -> long long {
            long long res = 1;
            base %= mod;
            while (exp > 0) {
                if (exp & 1) res = (res * base) % mod;
                base = (base * base) % mod;
                exp >>= 1;
            }
            return res;
        };
        long long p1 = power(n - 1, k);
        long long p2 = (k % 2 == 0) ? 1 : -1;
        long long inv_n = power(n, mod - 2);
        long long dp0 = (p1 + p2 * (n - 1)) % mod;
        if (dp0 < 0) dp0 += mod;
        dp0 = (dp0 * inv_n) % mod;
        long long dp1 = (p1 - p2) % mod;
        if (dp1 < 0) dp1 += mod;
        dp1 = (dp1 * inv_n) % mod;
        long long ans = 0;
