class Solution {
    public int numberOfWays(String s, String t, long k) {
        long mod = 1_000_000_007L;
        int n = s.length();
        String ss = (s + s).substring(0, 2 * n - 1);
        int[] pi = new int[n];
        int j = 0;
        for (int i = 1; i < n; i++) {
            while (j > 0 && t.charAt(i) != t.charAt(j)) j = pi[j - 1];
            if (t.charAt(i) == t.charAt(j)) j++;
            pi[i] = j;
        }
        int c = 0;
        j = 0;
        for (int i = 0; i < ss.length(); i++) {
            while (j > 0 && ss.charAt(i) != t.charAt(j)) j = pi[j - 1];
            if (ss.charAt(i) == t.charAt(j)) j++;
            if (j == n) {
                c++;
                j = pi[j - 1];
            }
        }
        long p1 = power(n - 1, k, mod);
        long p2 = (k % 2 == 0) ? 1 : -1;
        long invN = power(n, mod - 2, mod);
        long dp0 = (p1 + p2 * (n - 1)) % mod;
        if (dp0 < 0) dp0 += mod;
        dp0 = (dp0 * invN) % mod;
        long dp1 = (p1 - p2) % mod;
        if (dp1 < 0) dp1 += mod;
        dp1 = (dp1 * invN) % mod;
        long ans = s.equals(t) ? (dp0 + (c - 1) * dp1) % mod : (c * dp1) % mod;
        if (ans < 0) ans += mod;
        return (int) ans;
    }
    private long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

/**
 * @param {string} s
 * @param {string} t
 * @param {number} k
 * @return {number}
