var numberOfWays = function(s, t, k) {
    const mod = 1000000007n;
    const n = s.length;
    const bn = BigInt(n);
    const bk = BigInt(k);
    const ss = (s + s).slice(0, 2 * n - 1);
    const pi = new Int32Array(n);
    let j = 0;
    for (let i = 1; i < n; i++) {
        while (j > 0 && t[i] !== t[j]) j = pi[j - 1];
        if (t[i] === t[j]) j++;
        pi[i] = j;
    }
    let c = 0n;
    j = 0;
    for (let i = 0; i < ss.length; i++) {
        while (j > 0 && ss[i] !== t[j]) j = pi[j - 1];
        if (ss[i] === t[j]) j++;
        if (j === n) {
            c++;
            j = pi[j - 1];
        }
    }
    function power(base, exp) {
        let res = 1n;
        base = ((base % mod) + mod) % mod;
        while (exp > 0n) {
            if (exp & 1n) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return res;
    }
    const p1 = power(bn - 1n, bk);
    const p2 = (bk % 2n === 0n) ? 1n : -1n;
    const invN = power(bn, mod - 2n);
    let dp0 = ((p1 + p2 * (bn - 1n)) % mod + mod) % mod;
    dp0 = (dp0 * invN) % mod;
    let dp1 = ((p1 - p2) % mod + mod) % mod;
    dp1 = (dp1 * invN) % mod;
    let ans = 0n;
    if (s === t) ans = (dp0 + (c - 1n) * dp1) % mod;
    else ans = (c * dp1) % mod;
    return Number((ans + mod) % mod);
};
